//! Builds a [`rustls::ServerConfig`] from the `cert.pem` + `key.pem` PEM
//! files generated by the `init` command.
//!
//! Crypto provider: `ring` (installed once via [`ensure_crypto_provider`]).
//! TLS 1.2 stays enabled: we keep 1.2 + 1.3 for extension /
//! reverse-proxy compatibility.

use std::fs::File;
use std::io::BufReader;
use std::path::Path;
use std::sync::Once;

use rustls::ServerConfig;

use crate::error::{AggregatorError, AggregatorResult};

static INSTALL_CRYPTO_PROVIDER: Once = Once::new();

/// Installs `ring` as the default `rustls` provider —
/// idempotent (uses `std::sync::Once`).
pub fn ensure_crypto_provider() {
    INSTALL_CRYPTO_PROVIDER.call_once(|| {
        // `install_default` can only be called once per process,
        // otherwise it returns Err. `Once` prevents a second call.
        let _ = rustls::crypto::ring::default_provider().install_default();
    });
}

/// Loads cert + key from the PEM files and builds a rustls `ServerConfig`.
pub fn load_server_config(cert_path: &Path, key_path: &Path) -> AggregatorResult<ServerConfig> {
    ensure_crypto_provider();

    let cert_chain = {
        let mut reader = BufReader::new(File::open(cert_path)?);
        rustls_pemfile::certs(&mut reader)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| AggregatorError::Tls(format!("parse {}: {e}", cert_path.display())))?
    };
    if cert_chain.is_empty() {
        return Err(AggregatorError::Tls(format!(
            "aucun certificat trouvé dans {}",
            cert_path.display()
        )));
    }

    let private_key = {
        let mut reader = BufReader::new(File::open(key_path)?);
        rustls_pemfile::private_key(&mut reader)?
            .ok_or_else(|| AggregatorError::Tls(format!("clé absente de {}", key_path.display())))?
    };

    let config = ServerConfig::builder()
        .with_no_client_auth()
        .with_single_cert(cert_chain, private_key)
        .map_err(|e| AggregatorError::Tls(format!("ServerConfig: {e}")))?;

    Ok(config)
}
